package com.ryanjei.orushio.pve.paper;import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.map.*;import java.util.*;import org.junit.jupiter.api.Test;
class SetupMarkerOwnershipTest{@Test void PDCへ書くownership値はMarker種別SessionMap管理者だけを含む(){UUID admin=UUID.randomUUID();var token=new MapWorldGateway.SetupMarkerToken(SetupMarkerType.NORMAL_ENEMY_SPAWN,"session-a","map-a",admin);Map<String,String>values=PaperMapWorldGateway.markerMetadata(token);assertFalse(values.containsKey("markerId"));assertEquals("NORMAL_ENEMY_SPAWN",values.get("markerType"));assertEquals("session-a",values.get("sessionId"));assertEquals("map-a",values.get("mapId"));assertEquals(admin.toString(),values.get("administrator"));}
@Test void 全MarkerTypeへ重複なしMaterialを割り当てる(){Set<String>materials=new HashSet<>();for(SetupMarkerType type:SetupMarkerType.values())assertTrue(materials.add(PaperMapWorldGateway.materialName(type)),type+"のMaterialが重複しています。");assertEquals(18,materials.size());}
@Test void Survivalは補填しCreativeは複製しない(){assertTrue(PaperMapWorldGateway.replenishesInGameMode("SURVIVAL"));assertFalse(PaperMapWorldGateway.replenishesInGameMode("CREATIVE"));}}
